from itertools import permutations

def solve_puzzle():
    people = ['Blake', 'Casey', 'Emery', 'Jordan']
    colors = ['green', 'orange', 'red', 'yellow']
    pets = ['bird', 'dog', 'fish', 'horse']
    drinks = ['juice', 'milk', 'tea', 'water']

    # Try all possible assignments
    for p_perm in permutations(people):
        for c_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for d_perm in permutations(drinks):
                    # Build state: house -> {person, color, pet, drink}
                    state = {}
                    for i in range(4):
                        state[i+1] = {
                            'person': p_perm[i],
                            'color': c_perm[i],
                            'pet': pet_perm[i],
                            'drink': d_perm[i]
                        }

                    # Validate all constraints
                    if is_valid(state):
                        # Find who is in yellow house
                        for h in range(1, 5):
                            if state[h]['color'] == 'yellow':
                                return state[h]['person']

    return "No solution"

def is_valid(state):
    # Clue 1: Fish owner lives immediately left of Blake
    blake_h = next((h for h in range(1, 5) if state[h]['person'] == 'Blake'), None)
    if not blake_h or blake_h == 1 or state[blake_h-1]['pet'] != 'fish':
        return False

    # Clue 2: Bird owner is Jordan
    jordan_h = next((h for h in range(1, 5) if state[h]['person'] == 'Jordan'), None)
    if not jordan_h or state[jordan_h]['pet'] != 'bird':
        return False

    # Clue 3: Green house person is Blake
    green_h = next((h for h in range(1, 5) if state[h]['color'] == 'green'), None)
    if not green_h or state[green_h]['person'] != 'Blake':
        return False

    # Clue 4: Juice drinker lives next to orange house
    juice_h = next((h for h in range(1, 5) if state[h]['drink'] == 'juice'), None)
    orange_h = next((h for h in range(1, 5) if state[h]['color'] == 'orange'), None)
    if not juice_h or not orange_h or abs(juice_h - orange_h) != 1:
        return False

    # Clue 5: Casey owns horse
    casey_h = next((h for h in range(1, 5) if state[h]['person'] == 'Casey'), None)
    if not casey_h or state[casey_h]['pet'] != 'horse':
        return False

    # Clue 6: Jordan lives next to orange house
    if abs(jordan_h - orange_h) != 1:
        return False

    # Clue 7: Orange house person drinks water
    if state[orange_h]['drink'] != 'water':
        return False

    # Clue 8: Yellow house lives immediately left of milk drinker
    yellow_h = next((h for h in range(1, 5) if state[h]['color'] == 'yellow'), None)
    milk_h = next((h for h in range(1, 5) if state[h]['drink'] == 'milk'), None)
    if not yellow_h or not milk_h or milk_h != yellow_h + 1:
        return False

    # Clue 9: Red house lives immediately left of Blake
    red_h = next((h for h in range(1, 5) if state[h]['color'] == 'red'), None)
    if not red_h or red_h != blake_h - 1:
        return False

    return True

answer = solve_puzzle()
print(f"ANSWER: {answer}")
